local RadarGui, RadarCircle, RadarBlips = nil, nil, {}
local function makeRadar()
    RadarGui = Instance.new("ScreenGui")
    RadarGui.Name = "CVortexHubRadar"
    RadarGui.ResetOnSpawn = false
    RadarGui.IgnoreGuiInset = true
    RadarGui.DisplayOrder = 899
    local ok = pcall(function() RadarGui.Parent = (gethui and gethui()) or CoreGui end)
    if not ok or not RadarGui.Parent then RadarGui.Parent = LocalPlayer:WaitForChild("PlayerGui") end
